"""Create a self-contained responsive acceptance page from verified release data."""
from pathlib import Path
import html,json
OUT=Path(__file__).resolve().parent
r=json.loads((OUT/'release.json').read_text());assert r['success']
e=html.escape
cards=[('当前场景','只读取当前楼层','不聚合洞窟／世界，换层释放旧NPC，迟到响应隔离。'),('准确停靠','NPC坐标导航','可走格精确到达；墙／传送点占位使用可达相邻普通格并显示坐标。'),('完整名称','12px · 自适应换行','地点、NPC、区域均保留全名，内容高度决定页数，原生触屏标签完整。'),('可取消规划','256节点／片','分帧A*冻结地图修订；手动、锁定、跟随、换层取消并释放缓冲。')]
card_html=''.join(f'<article><span>{e(k)}</span><h2>{e(v)}</h2><p>{e(d)}</p></article>' for k,v,d in cards)
images=[]
for key in ['cave-npcs-desktop','cave-npc-arrived-desktop','cave-npcs-mobile','catalogue-mobile']:
 matches=list((OUT/'browser').glob('final-navigation-*'+key+'.png'))
 if matches:
  name=matches[0].relative_to(OUT).as_posix();images.append(f'<figure><a href="{e(name)}"><img loading="lazy" src="{e(name)}" alt="{e(key)}"></a><figcaption>{e(key)}</figcaption></figure>')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SA-1115-04 · 地图导航验收</title><style>
:root{color-scheme:light;--ink:#183c35;--soft:#536b62;--paper:#f7f5ec;--accent:#ac5632}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:56px 28px}header{border-top:5px solid var(--ink);padding-top:24px}small,.eyebrow{letter-spacing:.12em;color:var(--accent);font-weight:700}h1{font-size:clamp(32px,6vw,62px);line-height:1.15;max-width:850px;margin:16px 0 24px}h2{font-size:23px;line-height:1.35;margin:10px 0}p{color:var(--soft)}.lead{font-size:20px;max-width:830px}.status{display:inline-block;background:#dce9d9;border:1px solid #afc4ad;border-radius:4px;padding:5px 12px;font-weight:650}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:38px 0}article{padding:26px;border:1px solid #cdd4c8;background:#fffdf7;border-radius:6px}article span{font-size:12px;color:var(--accent);font-weight:700}.numbers{display:flex;flex-wrap:wrap;gap:24px;border-block:1px solid #b7c7bb;padding:24px 0}.numbers strong{display:block;font:700 30px/1.2 system-ui}.numbers span{font-size:13px;color:var(--soft)}section{margin-top:44px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{text-align:left;padding:12px 10px;border-bottom:1px solid #d3d9cb;vertical-align:top}th{background:#e8ecdf}a{color:#235e4c;text-decoration-thickness:1px;text-underline-offset:3px}.links{display:flex;flex-wrap:wrap;gap:12px 24px}.hash{font:12px/1.7 monospace;overflow-wrap:anywhere;background:#e8ecdf;padding:16px}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0}img{width:100%;display:block;border-radius:4px;border:1px solid #cdd4c8}figcaption{font-size:12px;color:var(--soft)}footer{border-top:2px solid var(--ink);margin-top:46px;padding-top:20px;color:var(--soft);font-size:13px}@media(max-width:600px){main{padding:28px 18px}.cards,.gallery{grid-template-columns:1fr}article{padding:20px}.lead{font-size:17px}td,th{padding:10px 6px;font-size:13px}}
</style><main><header><div class="eyebrow">STONEAGE / RELEASE REVIEW / 2026.11.15</div><h1>当前场景，<br>准确找到每一个目的地。</h1><div class="status">已核验 · VERSION</div><p class="lead">小地图入口目录、当前楼层NPC与完整名称排版；以真实资源、匹配Linux程序和Chromium证据交付。</p></header><div class="numbers"><div><strong>3309</strong><span>有效跨层地点</span></div><div><strong>1206</strong><span>地图覆盖</span></div><div><strong>CLIENT</strong><span>客户端／构建检查</span></div><div><strong>BROWSER</strong><span>真实Chromium检查</span></div></div><div class="cards">CARDS</div><section><h2>验收依据</h2><table><thead><tr><th>检查</th><th>结果与边界</th></tr></thead><tbody><tr><td>NPC处理范围</td><td>只枚举当前floor；最大实测100位、合并完整消息14030B；阿布洞窟一层1位／237B。非全世界聚合。</td></tr><tr><td>地点覆盖</td><td>4981物理入口／5002入口目的地对应；条件资格及随机分支由服务端判定。</td></tr><tr><td>回归</td><td>Go test／race／vet、TypeScript、独立BFS对照及取消／超时／墙格／warp边界。</td></tr><tr><td>真实交付</td><td>78文件HTTP逐字节一致；ELF两次构建一致；正常SIGTERM存档匹配；ZIP逐文件一致。</td></tr><tr><td>验证限制</td><td>Chromium触屏／视口模拟，不是实体Android／iOS／Safari认证。未重启或部署生产实例。运输NPC按最近快照显示，不预测追踪。</td></tr></tbody></table></section><section><h2>实际游戏截图</h2><div class="gallery">IMAGES</div></section><section><h2>可复核资料</h2><div class="links"><a href="ACCEPTANCE.md">完整验收</a><a href="SERVER-REVIEW.md">服务端与资源审计</a><a href="MOBILE-REVIEW.md">移动交互</a><a href="CLIENT-INTEGRATION-REVIEW.md">独立集成复核</a><a href="RESEARCH.md">本轮检索</a><a href="release.json">发行摘要</a><a href="browser/final-navigation.json">真实浏览器证据</a><a href="pathfinding-performance.json">路径性能测量</a></div><p class="hash">Linux AMD64 SHA-256<br>DIGEST</p><p>ZIP：FILES个文件／BYTES字节；完整替换上一版，未加入Assets原目录、凭据或数据库。</p></section><footer>SA-1115-04 · 证据区分预期红测、脚本断言修正、主动中断与最终通过。全部结论以匹配最终二进制的记录为准。</footer></main></html>'''
for key,value in {'VERSION':r['version'],'CLIENT':str(r['client_tests']),'BROWSER':str(r['browser']['checks']),'CARDS':card_html,'IMAGES':''.join(images),'DIGEST':r['binary_sha256'],'FILES':str(r['package']['files']),'BYTES':str(r['package']['bytes'])}.items():page=page.replace(key,value)
(OUT/'index.html').write_text(page)
